static int32_t uiWrap(int32_t value, int32_t low, int32_t high) {
  int32_t span = high - low + 1;
  int32_t past = (value - low) % span;
  return low + (past < 0 ? past + span : past);
}

static int32_t uiClamp(int32_t value, int32_t low, int32_t high) {
  return value < low ? low : value > high ? high : value;
}

static uint8_t uiDaysIn(uint16_t year, uint8_t month) {
  static const uint8_t days[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  bool leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
  return month == 2 && leap ? 29 : days[month - 1];
}

int32_t uiVar_sound = 1;
int32_t uiVar_signal = 0;
UiTimer uiTimer_left = {0, 0UL, 0UL, false, true};
int32_t uiVar_total = 0;
int32_t uiVar_typing = 1;
UiTimer uiTimer_lap = {0, 0, 0, false, false};

uint32_t uiRead(const UiTimer& timer) {
  uint32_t gone = timer.running ? millis() - timer.startedAt : 0;
  if (timer.down) {
    return gone >= timer.amount ? 0 : timer.amount - gone;
  }

  return timer.amount + gone;
}

void uiStart(UiTimer& timer) {
  if (timer.running) {
    return;
  }

  if (timer.down && timer.amount == 0) {
    timer.amount = timer.full;
  }

  if (!timer.down || timer.amount > 0) {
    timer.startedAt = millis();
    timer.running = true;
  }
}

void uiStop(UiTimer& timer) {
  timer.amount = uiRead(timer);
  timer.running = false;
}

void uiReset(UiTimer& timer) {
  timer.amount = timer.down ? timer.full : 0;
  timer.running = false;
}

void uiTimerSet(UiTimer& timer, int32_t seconds) {
  timer.amount = (uint32_t)seconds * 1000UL;
  timer.full = timer.amount;
  timer.running = false;
}

// Kept at the end of EEPROM. The mark says it is this project's, written with these variables.
static const uint16_t UI_SAVED_MARK = 0xF011;
static const uint16_t UI_SAVED_BYTES = sizeof(uint16_t) + 2 * sizeof(int32_t);

void uiSave() {
  int at = EEPROM.length() - UI_SAVED_BYTES;
  uint16_t mark = UI_SAVED_MARK;
  EEPROM.put(at, mark);
  at += sizeof mark;
  EEPROM.put(at, uiVar_sound);
  at += sizeof(int32_t);
  EEPROM.put(at, uiVar_signal);
  at += sizeof(int32_t);
#if defined(ARDUINO_ARCH_ESP32) || defined(ARDUINO_ARCH_ESP8266)
  EEPROM.commit();
#endif
}

static void uiLoadSaved() {
#if defined(ARDUINO_ARCH_ESP32) || defined(ARDUINO_ARCH_ESP8266)
  EEPROM.begin(512);
#endif
  int at = EEPROM.length() - UI_SAVED_BYTES;
  uint16_t mark = 0;
  EEPROM.get(at, mark);
  if (mark != UI_SAVED_MARK) {
    return;
  }

  at += sizeof mark;
  EEPROM.get(at, uiVar_sound);
  at += sizeof(int32_t);
  EEPROM.get(at, uiVar_signal);
  at += sizeof(int32_t);
}

// The date and the time, counted from when the board started.
struct UiClock {
  uint16_t year;
  uint8_t month;
  uint8_t day;
  uint8_t hour;
  uint8_t minute;
  uint8_t second;
};

static UiClock uiClock = {2026, 1, 1, 0, 0, 0};
static uint32_t uiClockAt;

static void uiClockBegin() {
  uiClockAt = millis();
}

static void uiClockTick() {
  while (millis() - uiClockAt >= 1000) {
    uiClockAt += 1000;
    if (++uiClock.second < 60) {
      continue;
    }

    uiClock.second = 0;
    if (++uiClock.minute < 60) {
      continue;
    }

    uiClock.minute = 0;
    if (++uiClock.hour < 24) {
      continue;
    }

    uiClock.hour = 0;
    if (++uiClock.day > uiDaysIn(uiClock.year, uiClock.month)) {
      uiClock.day = 1;
      if (++uiClock.month > 12) {
        uiClock.month = 1;
        uiClock.year++;
      }
    }
  }
}

static int32_t uiClockSeconds() {
  return uiClock.hour * 3600L + uiClock.minute * 60 + uiClock.second;
}

static int32_t uiClockDate() {
  return uiClock.year * 10000L + uiClock.month * 100 + uiClock.day;
}

static void uiClockSet(int32_t seconds) {
  uiClock.hour = seconds / 3600 % 24;
  uiClock.minute = seconds / 60 % 60;
  uiClock.second = seconds % 60;
  uiClockAt = millis();
}

