static bool uiCommit_screen1() {
  if (uiInputCount == 0) {
    return false;
  }

  int32_t minutes = uiInputNumber(0, 2, 4);
  int32_t seconds = uiInputNumber(2, 2, 4);
  if (seconds > 59) {
    return false;
  }

  uiTimerSet(uiTimer_left, minutes * 60 + seconds);
  return true;
}

static bool uiCommit_screen3() {
  if (uiInputCount < 6) {
    return false;
  }

  int32_t hours = uiInputNumber(0, 2, 6);
  int32_t minutes = uiInputNumber(2, 2, 6);
  int32_t seconds = uiInputNumber(4, 2, 6);
  if (hours > 23 || minutes > 59 || seconds > 59) {
    return false;
  }

  uiClockSet(hours * 3600 + minutes * 60 + seconds);
  return true;
}

static bool uiArrive() {
  switch (uiScreen) {
    case UI_SCREEN1:
      uiInputCount = 0;
      break;
    case UI_SCREEN3:
      uiInputCount = 0;
      break;
    default:
      break;
  }
  return true;
}

// Where it came from, so that the way back is the way it came.
struct UiVisit {
  UiScreen screen;
  uint8_t index;
  uint8_t top;
};

static const uint8_t UI_DEPTH = 8;
static UiVisit uiVisits[UI_DEPTH];
static uint8_t uiVisitCount;

static void uiEnter(UiScreen next) {
  if (next == uiScreen) {
    uiDirty = true;
    uiArrive();
    return;
  }

  // A screen already on the way here is gone back to, so that the way never grows without end.
  for (uint8_t i = uiVisitCount; i-- > 0;) {
    if (uiVisits[i].screen == next) {
      uiVisitCount = i;
      uiScreen = next;
      uiMenuIndex = uiVisits[i].index;
      uiMenuTop = uiVisits[i].top;
      uiDirty = true;
      return;
    }
  }

  if (uiVisitCount == UI_DEPTH) {
    memmove(uiVisits, uiVisits + 1, sizeof uiVisits - sizeof uiVisits[0]);
    uiVisitCount--;
  }

  uiVisits[uiVisitCount].screen = uiScreen;
  uiVisits[uiVisitCount].index = uiMenuIndex;
  uiVisits[uiVisitCount].top = uiMenuTop;
  uiVisitCount++;
  uiScreen = next;
  uiMenuIndex = 0;
  uiMenuTop = 0;
  uiDirty = true;
  uiArrive();
}

void uiBack() {
  if (uiVisitCount == 0) {
    return;
  }

  uiVisitCount--;
  uiScreen = uiVisits[uiVisitCount].screen;
  uiMenuIndex = uiVisits[uiVisitCount].index;
  uiMenuTop = uiVisits[uiVisitCount].top;
  uiDirty = true;
}

void uiGoTo(UiScreen screen) {
  uiEnter(screen);
}

void uiRedraw() {
  uiDirty = true;
}

UiScreen uiCurrent() {
  return uiScreen;
}

// What an event does on each screen, then on any screen. True if something took it.
static bool uiHandle(UiEvent event) {
  switch (uiScreen) {
    case UI_HOME:
      switch (event) {
        case UI_ON_KEY_A:
          uiEnter(UI_MENU2);
          uiDirty = true;
          return true;
        case UI_ON_KEY_HASH:
          uiEnter(UI_SCREEN1);
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_SCREEN1:
      switch (event) {
        case UI_ON_KEY_HASH:
          if (uiVar_typing) {
            if (!uiCommit_screen1()) {
              uiInputCount = 0;
              uiDirty = true;
              return true;
            }
            uiVar_total = uiClamp((int32_t)((uiRead(uiTimer_left) + 999) / 1000), 0, 5999);
            uiStart(uiTimer_left);
            uiVar_typing = (0) ? 1 : 0;
            uiDirty = true;
            return true;
          }
          if (uiTimer_left.running) { uiStop(uiTimer_left); } else { uiStart(uiTimer_left); }
          uiDirty = true;
          return true;
        case UI_ON_KEY_D:
          if (uiVar_typing) {
            if (uiInputCount > 0) { uiInputCount--; }
            uiDirty = true;
            return true;
          }
          uiReset(uiTimer_left);
          uiInputCount = 0;
          uiVar_typing = (1) ? 1 : 0;
          uiDirty = true;
          return true;
        case UI_ON_KEY_STAR:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_SCREEN2:
      switch (event) {
        case UI_ON_KEY_HASH:
          if (uiTimer_lap.running) { uiStop(uiTimer_lap); } else { uiStart(uiTimer_lap); }
          uiDirty = true;
          return true;
        case UI_ON_KEY_D:
          uiReset(uiTimer_lap);
          uiDirty = true;
          return true;
        case UI_ON_KEY_STAR:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_SCREEN3:
      switch (event) {
        case UI_ON_KEY_HASH:
          if (!uiCommit_screen3()) {
            uiInputCount = 0;
            uiDirty = true;
            return true;
          }
          uiBack();
          uiDirty = true;
          return true;
        case UI_ON_KEY_D:
          if (uiInputCount > 0) { uiInputCount--; }
          uiDirty = true;
          return true;
        case UI_ON_KEY_STAR:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_MENU1:
      switch (event) {
        case UI_ON_KEY_S2:
          if (uiMenuIndex > 0) {
            uiMenuIndex--;
            if (uiMenuIndex < uiMenuTop) {
              uiMenuTop = uiMenuIndex;
            }
            uiDirty = true;
          }
          return true;
        case UI_ON_KEY_S8:
          if (uiMenuIndex + 1 < 4) {
            uiMenuIndex++;
            if (uiMenuIndex >= uiMenuTop + 3) {
              uiMenuTop = uiMenuIndex - 2;
            }
            uiDirty = true;
          }
          return true;
        case UI_ON_KEY_HASH:
          switch (uiMenuIndex) {
            case 0:
              uiVar_sound = (!uiVar_sound) ? 1 : 0; uiSave();
              uiDirty = true;
              break;
            case 1:
              uiVar_signal = uiWrap((uiVar_signal + 1) % 2, 0, 1); uiSave();
              uiDirty = true;
              break;
            case 2:
              uiEnter(UI_SCREEN3);
              uiDirty = true;
              break;
            case 3:
              uiBack();
              uiDirty = true;
              break;
            default: break;
          }
          return true;
        case UI_ON_KEY_STAR:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_MENU2:
      switch (event) {
        case UI_ON_KEY_S2:
          if (uiMenuIndex > 0) {
            uiMenuIndex--;
            if (uiMenuIndex < uiMenuTop) {
              uiMenuTop = uiMenuIndex;
            }
            uiDirty = true;
          }
          return true;
        case UI_ON_KEY_S8:
          if (uiMenuIndex + 1 < 4) {
            uiMenuIndex++;
            if (uiMenuIndex >= uiMenuTop + 3) {
              uiMenuTop = uiMenuIndex - 2;
            }
            uiDirty = true;
          }
          return true;
        case UI_ON_KEY_HASH:
          switch (uiMenuIndex) {
            case 0:
              uiEnter(UI_SCREEN1);
              uiDirty = true;
              break;
            case 1:
              uiEnter(UI_SCREEN2);
              uiDirty = true;
              break;
            case 2:
              uiEnter(UI_MENU1);
              uiDirty = true;
              break;
            case 3:
              uiBack();
              uiDirty = true;
              break;
            default: break;
          }
          return true;
        case UI_ON_KEY_STAR:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    case UI_SCREEN4:
      switch (event) {
        case UI_ON_ANY_KEY:
          uiBack();
          uiDirty = true;
          return true;
        default:
          break;
      }
      break;
    default:
      break;
  }

  // From any screen.
  switch (event) {
    case UI_DONE_LEFT:
      if (uiVar_sound && uiVar_signal == 1) {
        tone(10, 1500, 1500);
        uiVar_typing = (1) ? 1 : 0;
        uiEnter(UI_SCREEN4);
        uiDirty = true;
        return true;
      }
      if (uiVar_sound) {
        tone(10, 1500, 300);
        uiVar_typing = (1) ? 1 : 0;
        uiEnter(UI_SCREEN4);
        uiDirty = true;
        return true;
      }
      uiVar_typing = (1) ? 1 : 0;
      uiEnter(UI_SCREEN4);
      uiDirty = true;
      return true;
    case UI_ON_KEY_B:
      uiEnter(UI_HOME);
      uiDirty = true;
      return true;
    default:
      break;
  }
  return false;
}

void uiSend(UiEvent event) {
  uiHandle(event);
}

// A press nothing on the screen took is still any key.
static void uiPress(UiEvent event) {
  if (!uiHandle(event)) {
    uiHandle(UI_ON_ANY_KEY);
  }
}

static const char uiKeys_kp1[4][4] = {{'1', '2', '3', 'A'}, {'4', '5', '6', 'B'}, {'7', '8', '9', 'C'}, {'*', '0', '#', 'D'}};
static byte uiRows_kp1[4] = {9, 8, 7, 6};
static byte uiColumns_kp1[4] = {5, 4, 3, 2};
static Keypad uiKeypad_kp1(makeKeymap(uiKeys_kp1), uiRows_kp1, uiColumns_kp1, 4, 4);

static void uiOnKey(char key) {
  switch (key) {
    case 'A':
      if (uiHandle(UI_ON_KEY_A)) {
        return;
      }

      break;
    case '#':
      if (uiHandle(UI_ON_KEY_HASH)) {
        return;
      }

      break;
    case 'D':
      if (uiHandle(UI_ON_KEY_D)) {
        return;
      }

      break;
    case '*':
      if (uiHandle(UI_ON_KEY_STAR)) {
        return;
      }

      break;
    case 'B':
      if (uiHandle(UI_ON_KEY_B)) {
        return;
      }

      break;
    case '2':
      if (uiHandle(UI_ON_KEY_S2)) {
        return;
      }

      break;
    case '8':
      if (uiHandle(UI_ON_KEY_S8)) {
        return;
      }

      break;
    default:
      break;
  }

  switch (uiScreen) {
    case UI_SCREEN1:
      if (key >= '0' && key <= '9') {
        uiInputAdd(key, 4);
        return;
      }

      break;
    case UI_SCREEN3:
      if (key >= '0' && key <= '9') {
        uiInputAdd(key, 6);
        return;
      }

      break;
    default:
      break;
  }

  uiHandle(UI_ON_ANY_KEY);
}

struct UiButton {
  uint8_t pin;
  bool activeLow;
  UiEvent event;
  bool pressed;
  bool raw;
  uint32_t changedAt;
};

static UiButton uiButtons[] = {
  {0, true, UI_NO_EVENT, false, false, 0},
};
static const uint8_t uiButtonCount = 0;

static void uiReadButtons() {
  uint32_t now = millis();
  for (uint8_t i = 0; i < uiButtonCount; i++) {
    UiButton& button = uiButtons[i];
    bool level = digitalRead(button.pin) == HIGH;
    bool raw = button.activeLow ? !level : level;
    if (raw != button.raw) {
      button.raw = raw;
      button.changedAt = now;
    }
    if (raw != button.pressed && now - button.changedAt >= 20) {
      button.pressed = raw;
      if (raw) {
        uiPress(button.event);
      }
    }
  }
}

void uiBegin() {
  uiDisplay.init();
  uiDisplay.backlight();
  uiDisplay.clear();
  memset(uiFrame, ' ', UI_CELLS);
  memset(uiPanel, ' ', UI_CELLS);
  for (uint8_t i = 0; i < uiButtonCount; i++) {
    pinMode(uiButtons[i].pin, uiButtons[i].activeLow ? INPUT_PULLUP : INPUT);
  }
  uiLoadSaved();
  uiClockBegin();
  uiArrive();
}

void uiUpdate() {
  uiClockTick();
  uiReadButtons();
  {
    char key = uiKeypad_kp1.getKey();
    if (key) {
      uiOnKey(key);
    }
  }

  if (uiTimer_left.running && uiRead(uiTimer_left) == 0) {
    uiTimer_left.running = false;
    uiTimer_left.amount = 0;
    uiDirty = true;
    uiHandle(UI_DONE_LEFT);
  }

  uint32_t now = millis();
  if (uiDirty || now - uiDrawnAt >= 100UL) {
    uiDirty = false;
    uiDrawnAt = now;
    uiDrawScreen();
  }

  uiFlush();
}
